import {useState} from 'react'
import {graphql, useMutation} from 'react-relay'

import {useQueryParam} from '../../../../../../../hooks/routes'
import {extractErrorFromRelay} from '../../../../../../../relay/extractErrorFromRelay'
import {toProjectId} from '../../../../../../../types'
import {getAccountRootProjectId} from '../../../../PipelinesPages.consts'

import type {useVcsSshGenerateDialogMutation} from './__generated__/useVcsSshGenerateDialogMutation.graphql'
import {SshGenerateAlgorithmType} from './VcsSshGenerateDialog.const'
import type {SshGenerateAlgorithmEnumType} from './VcsSshGenerateDialog.types'

const generateVcsSshMutation = graphql`
  mutation useVcsSshGenerateDialogMutation(
    $projectId: ProjectId!
    $keyName: String!
    $keyType: String!
  ) {
    generatedProjectSshKeys(projectId: $projectId, keyName: $keyName, keyType: $keyType) {
      name
      encrypted
      publicKey
    }
  }
`

function useVcsSshGenerateDialog(onCompleted: () => void) {
  const projectIdString = useQueryParam('projectId')
  const projectId =
    projectIdString != null ? toProjectId(projectIdString) : getAccountRootProjectId()
  const [vcsSshGenerateErrorMessage, setVcsSshGenerateErrorMessage] = useState<string | null>()
  const [vcsSshGenerate, isVcsSshGenerateLoading] =
    useMutation<useVcsSshGenerateDialogMutation>(generateVcsSshMutation)
  const [sshKeyName, setSshKeyName] = useState<string>('')
  const [generateAlgorithm, setGenerateAlgorithm] = useState<SshGenerateAlgorithmEnumType>(
    SshGenerateAlgorithmType.ED25519,
  )
  const changeSshKeyNameInputHandler = ({target}: React.ChangeEvent<HTMLInputElement>) => {
    const {value} = target

    setSshKeyName(value)
    setVcsSshGenerateErrorMessage(null)
  }
  const generateSshKeyErorrHandler = (error: Error | null) => {
    if (error) {
      const extractedErrorMessage = extractErrorFromRelay(error).message

      setVcsSshGenerateErrorMessage(extractedErrorMessage)
    }
  }
  const generateSshKeyHandler = () => {
    vcsSshGenerate({
      variables: {
        projectId,
        keyName: sshKeyName,
        keyType: generateAlgorithm,
      },
      onError: generateSshKeyErorrHandler,
      onCompleted,
    })
  }
  const isDisabledGenerateButton = !sshKeyName
  const clickGenerateAlgorithmButtonHandler =
    (value: SshGenerateAlgorithmEnumType) => (_: React.MouseEvent<HTMLButtonElement>) => {
      setGenerateAlgorithm(value)
      setVcsSshGenerateErrorMessage(null)
    }
  const clickGenerateSshKeyButtonHandler = () => {
    generateSshKeyHandler()
    setVcsSshGenerateErrorMessage(null)
  }

  return {
    sshKeyName,
    generateAlgorithm,
    isDisabledGenerateButton,
    isVcsSshGenerateLoading,
    vcsSshGenerateErrorMessage,
    changeSshKeyNameInputHandler,
    clickGenerateAlgorithmButtonHandler,
    clickGenerateSshKeyButtonHandler,
  }
}

export default useVcsSshGenerateDialog
