import {useState} from 'react'
import {graphql, useMutation} from 'react-relay'

import {useQueryParam} from '../../../../../../../hooks/routes'
import {extractErrorFromRelay} from '../../../../../../../relay/extractErrorFromRelay'
import {toProjectId} from '../../../../../../../types'
import {getAccountRootProjectId} from '../../../../PipelinesPages.consts'

import type {useVcsSshDeleteDialogMutation} from './__generated__/useVcsSshDeleteDialogMutation.graphql'

const deleteVcsSshMutation = graphql`
  mutation useVcsSshDeleteDialogMutation($projectId: ProjectId!, $keyName: String!) {
    deleteProjectSshKeys(projectId: $projectId, keyName: $keyName)
  }
`

function useVcsSshDeleteDialog(keyName: string, onCompleted: () => void) {
  const projectIdString = useQueryParam('projectId')
  const projectId =
    projectIdString != null ? toProjectId(projectIdString) : getAccountRootProjectId()
  const [vcsSshDeleteErrorMessage, setVcsSshDeleteErrorMessage] = useState<string | null>()
  const [vcsSshDelete, isVcsSshDeleteLoading] =
    useMutation<useVcsSshDeleteDialogMutation>(deleteVcsSshMutation)
  const vcsSshDeleteErrorHandler = (error: Error | null) => {
    if (error) {
      const extractedErrorMessage = extractErrorFromRelay(error).message

      setVcsSshDeleteErrorMessage(extractedErrorMessage)
    }
  }
  const clickButtonDeleteHandler = () => {
    vcsSshDelete({
      variables: {
        projectId,
        keyName,
      },
      onCompleted,
      onError: vcsSshDeleteErrorHandler,
    })
  }

  return {
    isVcsSshDeleteLoading,
    vcsSshDeleteErrorMessage,
    clickButtonDeleteHandler,
  }
}

export default useVcsSshDeleteDialog
