import type {InputAttrs} from '@jetbrains/ring-ui-built/components/input/input'
import RingInput from '@jetbrains/ring-ui-built/components/input/input'
import classNames from 'classnames'
import {memo} from 'react'

import styles from './Input.module.css'

function Input({inputClassName, ...props}: InputAttrs) {
  const inputClassNames = classNames(styles.input, inputClassName, {
    [styles.multiline]: props.multiline,
  })

  return <RingInput inputClassName={inputClassNames} {...props} />
}

export default memo(Input)
