import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Size} from '@jetbrains/ring-ui-built/components/input/input'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'

import Input from '../../../Input'

import useVcsSshGenerateDialog from './useVcsSshGenerateDialog'
import {dialogTitle, sshGenerateAlgorithmTypeList} from './VcsSshGenerateDialog.const'
import type {VcsSshGenerateDialogProps} from './VcsSshGenerateDialog.types'

import styles from './VcsSshGenerateDialog.module.css'

function VcsSshGenerateDialog({onClose, onGenerate}: VcsSshGenerateDialogProps) {
  const {
    sshKeyName,
    generateAlgorithm,
    isVcsSshGenerateLoading,
    isDisabledGenerateButton,
    vcsSshGenerateErrorMessage,
    changeSshKeyNameInputHandler,
    clickGenerateAlgorithmButtonHandler,
    clickGenerateSshKeyButtonHandler,
  } = useVcsSshGenerateDialog(onGenerate)

  return (
    <Dialog
      show
      trapFocus
      showCloseButton
      closeButtonInside
      onCloseAttempt={onClose}
      label={dialogTitle}
    >
      <Header>{dialogTitle}</Header>
      <Content>
        <ButtonGroup label="Key type" className={styles.buttonGroupToggle}>
          {sshGenerateAlgorithmTypeList.map(({name, value}) => (
            <Button
              key={value}
              name={value}
              className={styles.buttonToggle}
              active={value === generateAlgorithm}
              onClick={clickGenerateAlgorithmButtonHandler(value)}
            >
              {name}
            </Button>
          ))}
        </ButtonGroup>
        <Input
          label="Key name"
          value={sshKeyName}
          size={Size.FULL}
          onChange={changeSshKeyNameInputHandler}
        />
      </Content>
      {vcsSshGenerateErrorMessage && (
        <div className={styles.errorMessage}>{vcsSshGenerateErrorMessage}</div>
      )}
      <Panel>
        <Button
          primary
          title="Generate"
          loader={isVcsSshGenerateLoading}
          disabled={isDisabledGenerateButton}
          onClick={clickGenerateSshKeyButtonHandler}
        >
          {'Generate'}
        </Button>
        <Button disabled={isVcsSshGenerateLoading} title="Close" onClick={onClose}>
          {'Close'}
        </Button>
      </Panel>
    </Dialog>
  )
}

export default VcsSshGenerateDialog
