import alert from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import {useMemo, useState} from 'react'

import type {ProjectId} from '../../../../../../../types'
import {getExtractErrorMessages} from '../../../../EditPipelinePage/EditPipelinePage.utils'
import {pipelinesApi} from '../../../../services/pipelinesApi'

const alertMessageTimeout = 2000 // ms

function useVcsSshUploadDialog(projectId: ProjectId, onClose: (keyName?: string) => void) {
  const [uploadedFile, setUploadedFile] = useState<File | null>(null)
  const [sshKeyName, setSshKeyName] = useState<string>('')
  const [isSshKeyUploading, setSshKeyUploading] = useState<boolean>(false)
  const [uploadProjectSshKey, {error: uploadProjectSshKeyError, reset: uploadProjectSshKeyReset}] =
    pipelinesApi.endpoints.uploadProjectSshKey.useMutation()
  const filesSelectedUploadHandler = (files: File[]) => {
    const [file] = files

    setUploadedFile(file)
    uploadProjectSshKeyReset()

    if (!sshKeyName) {
      setSshKeyName(file.name)
    }
  }
  const changeSshKeyNameInputHandler = ({target}: React.ChangeEvent<HTMLInputElement>) => {
    const {value} = target

    setSshKeyName(value)
  }
  const closeDialogHandler = () => onClose()
  const clickUploadSshKeyButtonHandler = () => {
    if (uploadedFile != null) {
      const reader = new FileReader()
      const loadReaderFileHandler = async () => {
        try {
          const fileContent = reader.result as string

          await uploadProjectSshKey({
            fileName: sshKeyName,
            file: fileContent,
            projectId,
          }).unwrap()

          alert.message(`SSH key successfully uploaded and applied`, alertMessageTimeout)

          onClose(sshKeyName)
        } catch (error) {
          // eslint-disable-next-line no-console
          console.error(error)
        }
        setSshKeyUploading(false)
      }

      setSshKeyUploading(true)

      reader.onload = loadReaderFileHandler

      reader.readAsText(uploadedFile)
    }
  }
  const isDisabledUploadButton = !sshKeyName || !uploadedFile
  const errorMessage = useMemo(
    () =>
      getExtractErrorMessages(uploadProjectSshKeyError)
        ?.map(({message}) => message)
        ?.join('\n'),
    [uploadProjectSshKeyError],
  )

  return {
    sshKeyName,
    errorMessage,
    isSshKeyUploading,
    isDisabledUploadButton,
    clickUploadSshKeyButtonHandler,
    changeSshKeyNameInputHandler,
    filesSelectedUploadHandler,
    closeDialogHandler,
  }
}

export default useVcsSshUploadDialog
