import {useState} from 'react'
import type {PreloadedQuery} from 'react-relay'
import {useQueryLoader} from 'react-relay'

import {getAccountRootProjectId} from '../PipelinesPages/PipelinesPages.consts'

import type {SharedSettingsSshKeysPageQuery} from './__generated__/SharedSettingsSshKeysPageQuery.graphql'
import {query} from './SharedSettingsSshKeysPage.queries'

function useSharedSettingsSshKeysPage(queriesMain: PreloadedQuery<SharedSettingsSshKeysPageQuery>) {
  const [sshKeysRef, loadSshKeysQuery] = useQueryLoader<SharedSettingsSshKeysPageQuery>(
    query,
    queriesMain,
  )
  const [isShowVcsSshGenerateDialog, setShowVcsSshGenerateDialog] = useState<boolean>(false)
  const [isShowSshUploadDialog, setShowSshUploadDialog] = useState<boolean>(false)
  const [deleteSshKeyName, setDeleteSshKeyName] = useState<string | null>(null)
  const clickUploadSshKeyButtonHandler = () => setShowSshUploadDialog(true)
  const uploadSshKeysQuery = () =>
    loadSshKeysQuery(
      {
        projectId: getAccountRootProjectId(),
      },
      {fetchPolicy: 'network-only'},
    )
  const closeVcsSshUploadDialogHandler = () => {
    setShowSshUploadDialog(false)
    uploadSshKeysQuery()
  }
  const deleteSshKeysTableHandler = (value: string) => setDeleteSshKeyName(value)
  const cancelVcsSshDeleteDialogHandler = () => setDeleteSshKeyName(null)
  const deleteVcsSshDeleteDialogHandler = () => {
    setDeleteSshKeyName(null)
    uploadSshKeysQuery()
  }
  const closeVcsSshGenerateDialogHandler = () => setShowVcsSshGenerateDialog(false)
  const clickGenerateSshKeyButtonHandler = () => setShowVcsSshGenerateDialog(true)
  const generateVcsSshGenerateDialogHandler = () => {
    closeVcsSshGenerateDialogHandler()
    uploadSshKeysQuery()
  }

  return {
    sshKeysRef,
    deleteSshKeyName,
    isShowSshUploadDialog,
    isShowVcsSshGenerateDialog,
    closeVcsSshGenerateDialogHandler,
    clickUploadSshKeyButtonHandler,
    closeVcsSshUploadDialogHandler,
    deleteSshKeysTableHandler,
    cancelVcsSshDeleteDialogHandler,
    deleteVcsSshDeleteDialogHandler,
    clickGenerateSshKeyButtonHandler,
    generateVcsSshGenerateDialogHandler,
  }
}

export default useSharedSettingsSshKeysPage
