import LockIcon from '@jetbrains/icons/lock.svg'
import TrashIcon from '@jetbrains/icons/trash-12px.svg'
import alert from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {useCallback} from 'react'
import type * as React from 'react'
import type {PreloadedQuery} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'

import {copyClipboard} from '../../../../utils/clipboard'
import Grid from '../../../common/Grid/Grid'
import RowGroup from '../../../common/Grid/RowGroup'
import type {SharedSettingsSshKeysPageQuery} from '../__generated__/SharedSettingsSshKeysPageQuery.graphql'
import {query} from '../SharedSettingsSshKeysPage.queries'

import SharedSettingsSshKeysTableEmpty from './SharedSettingsSshKeysTableEmpty/SharedSettingsSshKeysTableEmpty'

import styles from './SharedSettingsSshKeysTable.module.css'

type SharedSettingsSshKeysTableProps = {
  queryRef: PreloadedQuery<SharedSettingsSshKeysPageQuery>
  onDelete: (value: string) => void
}

const messageTimeout = 2000 // ms
const gridId = 'sshKeysTable'

function SharedSettingsSshKeysTable({queryRef, onDelete}: SharedSettingsSshKeysTableProps) {
  const {getProjectSshKeys} = usePreloadedQuery(query, queryRef)
  const sshKeys = getProjectSshKeys?.sshKey
  const clickDeleteButtonHandler = useCallback(
    (value: string) => (_: React.MouseEvent<HTMLButtonElement>) => value && onDelete(value),
    [onDelete],
  )
  const clickCopyButtonHandler = useCallback(
    (value: string) => async () => {
      try {
        await copyClipboard(value)
        alert.message(`Public key has been copied`, messageTimeout)
      } catch (error) {
        // eslint-disable-next-line no-console
        console.error(error)
      }
    },
    [],
  )

  if (!sshKeys?.length) {
    return <SharedSettingsSshKeysTableEmpty />
  }

  return (
    <Grid gridId={gridId} className={styles.table}>
      <RowGroup gridId={gridId} className={styles.tableHeader}>
        <div className={styles.tableTh}>{'Key name'}</div>
        <div className={styles.tableTh} />
      </RowGroup>
      {sshKeys?.map(({name, encrypted, publicKey}) => (
        <RowGroup key={name} gridId={gridId}>
          <div className={styles.tableTd}>
            <div className={styles.tableKeyName}>
              {name}
              {encrypted && (
                <Tooltip title="Encrypted">
                  <LockIcon width="12" height="12" />
                </Tooltip>
              )}
            </div>
          </div>
          <div className={styles.tableTd}>
            <div className={styles.actionButtons}>
              {publicKey && (
                <Button title={`Copy public ${name}`} onClick={clickCopyButtonHandler(publicKey)}>
                  {'Copy public key'}
                </Button>
              )}
              {name && (
                <IconButton
                  title={`Delete ${name}`}
                  withBorder
                  icon={TrashIcon}
                  onClick={clickDeleteButtonHandler(name)}
                />
              )}
            </div>
          </div>
        </RowGroup>
      ))}
    </Grid>
  )
}

export default SharedSettingsSshKeysTable
