import AddIcon from '@jetbrains/icons/add.svg'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {Fragment} from 'react'
import type {EntryPointProps} from 'react-relay'

import VcsSshDeleteDialog from '../PipelinesPages/components/VcsAnyRepositoryAuthenticationForm/VcsSshRepositoryAuthenticationForm/VcsSshDeleteDialog/VcsSshDeleteDialog'
import VcsSshGenerateDialog from '../PipelinesPages/components/VcsAnyRepositoryAuthenticationForm/VcsSshRepositoryAuthenticationForm/VcsSshGenerateDialog/VcsSshGenerateDialog'
import VcsSshUploadDialog from '../PipelinesPages/components/VcsAnyRepositoryAuthenticationForm/VcsSshRepositoryAuthenticationForm/VcsSshUploadDialog/VcsSshUploadDialog'
import {getAccountRootProjectId} from '../PipelinesPages/PipelinesPages.consts'

import type {SharedSettingsSshKeysPageQuery} from './__generated__/SharedSettingsSshKeysPageQuery.graphql'
import SharedSettingsSshKeysTable from './SharedSettingsSshKeysTable/SharedSettingsSshKeysTable'
import useSharedSettingsSshKeysPage from './useSharedSettingsSshKeysPage'

import styles from './SharedSettingsSshKeysPage.module.css'

type Queries = {
  main: SharedSettingsSshKeysPageQuery
}

function SharedSettingsSshKeysPage({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  const projectId = getAccountRootProjectId() // TODO when we will add this page to the project settings, we will need to pass the projectId as a prop
  const {
    sshKeysRef,
    deleteSshKeyName,
    isShowSshUploadDialog,
    isShowVcsSshGenerateDialog,
    closeVcsSshGenerateDialogHandler,
    clickUploadSshKeyButtonHandler,
    closeVcsSshUploadDialogHandler,
    deleteSshKeysTableHandler,
    cancelVcsSshDeleteDialogHandler,
    deleteVcsSshDeleteDialogHandler,
    clickGenerateSshKeyButtonHandler,
    generateVcsSshGenerateDialogHandler,
  } = useSharedSettingsSshKeysPage(queries.main)

  return (
    <Fragment>
      <div className={styles.subTitleText}>{'Supported formats: OpenSSH private keys.'}</div>
      <div className={styles.subTitleButtonGroup}>
        <IconButton
          withBorder
          height={ControlsHeight.M}
          icon={AddIcon}
          title="Upload SSH Key"
          onClick={clickUploadSshKeyButtonHandler}
        >
          {'Upload SSH Key'}
        </IconButton>
        <IconButton
          withBorder
          height={ControlsHeight.M}
          icon={AddIcon}
          title="Generate SSH key"
          onClick={clickGenerateSshKeyButtonHandler}
        >
          {'Generate SSH key'}
        </IconButton>
      </div>
      {sshKeysRef && (
        <SharedSettingsSshKeysTable onDelete={deleteSshKeysTableHandler} queryRef={sshKeysRef} />
      )}
      {isShowVcsSshGenerateDialog && (
        <VcsSshGenerateDialog
          onClose={closeVcsSshGenerateDialogHandler}
          onGenerate={generateVcsSshGenerateDialogHandler}
        />
      )}
      {deleteSshKeyName && (
        <VcsSshDeleteDialog
          keyName={deleteSshKeyName}
          onDelete={deleteVcsSshDeleteDialogHandler}
          onCancel={cancelVcsSshDeleteDialogHandler}
        />
      )}
      {isShowSshUploadDialog && (
        <VcsSshUploadDialog projectId={projectId} onClose={closeVcsSshUploadDialogHandler} />
      )}
    </Fragment>
  )
}

export type SharedSettingsSshKeysPageComponent = typeof SharedSettingsSshKeysPage

export default SharedSettingsSshKeysPage
