import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'

import useVcsSshDeleteDialog from './useVcsSshDeleteDialog'

import styles from './VcsSshDeleteDialog.module.css'

const dialogTitle = 'Delete token'

type VcsSshDeleteDialogProps = {
  keyName: string
  onCancel: () => void
  onDelete: () => void
}

function VcsSshDeleteDialog({keyName, onCancel, onDelete}: VcsSshDeleteDialogProps) {
  const {isVcsSshDeleteLoading, vcsSshDeleteErrorMessage, clickButtonDeleteHandler} =
    useVcsSshDeleteDialog(keyName, onDelete)

  return (
    <Dialog
      show
      trapFocus
      showCloseButton
      closeButtonInside
      onCloseAttempt={onCancel}
      label={dialogTitle}
    >
      <Header>{dialogTitle}</Header>
      <Content>
        {
          'Are you sure you want to delete this key? Make sure to check usage before deleting the key.'
        }
      </Content>
      {vcsSshDeleteErrorMessage && (
        <div className={styles.errorMessage}>{vcsSshDeleteErrorMessage}</div>
      )}
      <Panel>
        <Button
          primary
          loader={isVcsSshDeleteLoading}
          title="Delete"
          onClick={clickButtonDeleteHandler}
        >
          {'Delete'}
        </Button>
        <Button title="Cancel" onClick={onCancel}>
          {'Cancel'}
        </Button>
      </Panel>
    </Dialog>
  )
}

export default VcsSshDeleteDialog
